function [k12,k21,k23,k32,k31,k13] = krates(xin,reach,kRT,phos)G1 = 0.0;G2 = -4.3 + kRT*(xin - reach)^2;G3 = -4.3 + kRT*xin^2 + log(0.000189*phos);k12 = 1000.0*sqrt(kRT/(2.0*pi))*exp(-kRT*((xin - reach)^2)/2.0);k21 = k12*exp(G2 - G1);k23 = (100.0 + 500.0*exp(-1.0*xin))*1.0;k32 = k23*exp(G3 - G2);if (xin >= 0.0) k31 = 2.0*xin; else k31 = -100.0*xin; endk31 = 100*k31;k13 = 0.0;	